import * as C from './core.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4 M8 14h2 M14 14h2 M8 18h2',visits:'M8 4h8v3H8z M6 5H4v16h16V5h-2 M8 12h8 M8 16h5',people:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-3c0-4 14-4 14 0v3 M17 5a3 3 0 0 1 0 6 M19 15c3 0 3 3 3 6',check:'m5 12 4 4L20 5',file:'M6 3h8l5 5v13H6z M14 3v6h5 M9 13h7 M9 17h7',chart:'M4 3v18h17 M8 17v-5 M13 17V7 M18 17V4',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M12 6v6l4 2',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4z M10 21h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M10 2h4l1 4 4 1 3 4v3l-4 2-1 4-4 2h-3l-2-4-4-1-2-4v-3l4-2 1-4z',arrow:'m5 12h14 m-5-5 5 5-5 5',plus:'M12 5v14 M5 12h14',download:'M12 3v12 m-5-5 5 5 5-5 M4 17v4h16v-4',search:'M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16 m6-2 6 6',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6z m-5 10 3 3 7-7',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h1 M3 12h1 M3 18h1',logout:'M10 3H4v18h6 M9 12h12 m-5-5 5 5-5 5'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`;
let app,loadError='';
try{app=new C.Store(C.loadState(localStorage,window.SPIC_INITIAL,()=>C.seedState()));}catch(error){loadError=error.message;app=new C.Store(C.seedState());}
if(!loadError)app.storage=localStorage;
let tab='overview',worker='a1',week=C.localDay(new Date()),q={},docType='payments',requestArchive=false,importPreview=null;
const roleNames={admin:'Administratorius',coordinator:'Koordinatorius',assistant:'Asistentas'};
const nav=[['overview','Apžvalga','dashboard'],['mine','Mano diena','people'],['calendar','Vizitų planas','calendar'],['visits','Suteiktos paslaugos','visits'],['requests','Taisymų prašymai','check'],['clients','Paslaugos gavėjai','people'],['reports','Ataskaitos','chart'],['payments','Mokėjimo pranešimai','file'],['serviceActs','Paslaugų aktai','file'],['reminders','Priminimai','bell'],['activities','Leistinos veiklos','list'],['assistants','Asistentai','people'],['import','Duomenų importas','download'],['audit','Veiksmų istorija','clock'],['settings','Nustatymai','settings']];
const state=()=>app.s, actor=()=>app.actor;
const manager=()=>C.isManager(actor());
const cn=id=>state().clients.find(c=>c.id===id)?.name||id;
const an=id=>state().assistants.find(a=>a.id===id)?.name||id;
const day=()=>app.day;
const month=()=>day().slice(0,7);
const time=iso=>iso?new Date(iso).toLocaleTimeString('lt-LT',{hour:'2-digit',minute:'2-digit'}):'–';
const dt=iso=>iso?new Date(iso).toLocaleString('lt-LT',{dateStyle:'short',timeStyle:'short'}):'–';
const money=C.fmtMoney, fh=C.fmtHours;
const button=(label,action,id='',style='secondary',extra='')=>`<button type="button" class="btn ${style}" data-action="${action}" data-id="${e(id)}" ${extra}>${label}</button>`;
const empty=(title,detail,cta='')=>`<div class="empty">${icon('file')}<h3>${e(title)}</h3><p>${e(detail)}</p>${cta}</div>`;
const badge=(label,tone='neutral')=>`<span class="badge ${tone}">${e(label)}</span>`;
const statusLabels={running:'Vyksta',submitted:'Laukia patikros',approved:'Patikrinta',returned:'Grąžinta taisyti',pending:'Laukia sprendimo',rejected:'Atmesta',used:'Panaudota',planned:'Suplanuota',completed:'Įvykdyta',cancelled:'Atšaukta',draft:'Projektas'};
const status=(value)=>badge(statusLabels[value]||value,['approved','completed','used'].includes(value)?'green':['returned','rejected','cancelled'].includes(value)?'red':['running','pending','submitted','draft'].includes(value)?'amber':'neutral');
const selectOptions=(items,value,all='')=>(all!==null?`<option value="">${e(all)}</option>`:'')+items.map(x=>`<option value="${e(x.id)}" ${x.id===value?'selected':''}>${e(x.name)}</option>`).join('');
const clientOptions=(value,history=false)=>selectOptions(state().clients.filter(c=>manager()||c.assistant===worker||history&&C.canAccessClient(state(),actor(),c)),value,null);
const assistantOptions=(value,all='Visi asistentai')=>selectOptions(state().assistants,value,all);
const field=(label,name,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${e(value)}" ${extra}></label>`;
const sf=(label,name,html)=>`<label class="field">${label}<select name="${name}">${html}</select></label>`;
const textarea=(label,name,value='',extra='')=>`<label class="field full">${label}<textarea name="${name}" ${extra}>${e(value)}</textarea></label>`;
const check=(name,label,checked=false,value='on',disabled=false)=>`<label class="check"><input type="checkbox" name="${name}" value="${e(value)}" ${checked?'checked':''} ${disabled?'disabled':''}><span>${label}</span></label>`;
const stats=(items)=>`<div class="stats">${items.map(([label,value,foot,ic,tone])=>`<div class="stat ${tone||''}"><span class="stat-icon">${icon(ic||'chart')}</span><div><span class="muted">${label}</span><strong>${value}</strong><small>${foot||''}</small></div></div>`).join('')}</div>`;
const table=(heads,rows,cls='')=>`<div class="table-wrap"><table class="${cls}"><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
const notice=(text,tone='info')=>`<div class="notice ${tone}">${icon(tone==='warn'?'bell':'shield')}<span>${text}</span></div>`;
function toast(message,error=false){const n=$('#toast');n.textContent=message;n.className=error?'show error':'show';clearTimeout(toast.timer);toast.timer=setTimeout(()=>n.className='',6000);}
function safe(fn){try{const result=fn();if(result instanceof Promise)result.catch(error=>toast(error.message,true));}catch(error){toast(error.message,true);}}
function canTab(id){if(actor().role==='assistant')return ['mine','calendar','visits','requests','serviceActs'].includes(id);if(actor().role==='coordinator')return !['mine','activities','assistants','import','settings'].includes(id);return id!=='mine';}
function pageHeader(title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">ASMENINĖS PAGALBOS VALDYMAS</div><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
function render(){
  if(!canTab(tab))tab=actor().role==='assistant'?'mine':'overview';
  $('#sidebar').innerHTML=`<a class="brand" href="#" data-action="home"><span class="brand-mark">s<span>•</span></span><span>SPIC<small>Asmeninė pagalba</small></span></a><div class="nav-label">DARBO APLINKA</div><nav aria-label="Pagrindinis meniu">${nav.filter(([id])=>canTab(id)).map(([id,label,ic])=>`<button class="nav-item ${id===tab?'active':''}" data-action="nav" data-id="${id}">${icon(ic)}<span>${label}</span>${id==='requests'&&state().requests.some(r=>r.status==='pending')?`<span class="count">${state().requests.filter(r=>r.status==='pending').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><span class="demo-dot"></span> SUSITIKIMO DEMONSTRACIJA<br><small>v13 · tik pavyzdiniai duomenys</small></div>`;
  $('#topbar').innerHTML=`<div class="top-left"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Atidaryti meniu">${icon('list')}</button><span class="breadcrumb">SPIC <span>/</span> ${nav.find(n=>n[0]===tab)?.[1]}</span></div><div class="top-actions"><button class="network ${state().online?'':'offline'}" data-action="network" title="Imituoti ryšio būseną"><span></span>${state().online?'Prisijungta':'Be ryšio'}${state().pending.length?' · '+state().pending.length+' eilėje':''}</button><button class="icon-btn" data-action="guide" aria-label="Demonstracijos vadovas">?</button><label class="role-switch"><span class="sr-only">Demonstracijos rolė</span><select id="role-select">${Object.entries(roleNames).map(([id,n])=>`<option value="${id}" ${actor().role===id?'selected':''}>${n}</option>`).join('')}</select></label><span class="avatar">${actor().role==='assistant'?an(worker).split(' ').map(s=>s[0]).slice(0,2).join(''):'SP'}</span></div>`;
  const warnings=state().clients.filter(c=>manager()||c.assistant===worker).map(c=>({c,text:C.usageWarning(state(),c,month())})).filter(x=>x.text);
  const views={overview:overview,mine:mine,calendar:calendar,visits:visits,requests:requests,clients:clients,reports:reports,payments:()=>documents('payments'),serviceActs:()=>documents('serviceActs'),reminders:reminders,activities:activities,assistants:assistants,import:importView,audit:audit,settings:settings};
  $('#main').innerHTML=(loadError?notice(e(loadError)+' Demonstraciniai duomenys neišsaugomi, kol neatkurtas saugojimas.','warn'):'')+(!state().online?notice(state().settings.offline?'Dirbate be ryšio. Įrašai išsaugomi šiame įrenginyje. Sinchronizavimas su serveriu šioje demonstracijoje imituojamas.':'Nėra ryšio. Pagrindiniame variante nauji įrašai negalimi. Darbo be interneto parinktį įjungia administratorius.','warn'):'')+(warnings.length?notice(warnings.map(x=>'<b>'+e(x.c.name)+'</b>: '+e(x.text)).join('<br>'),'warn'):'')+views[tab]();
  $('#sidebar').classList.remove('open');
}
function overview(){
  const [from,to]=C.monthBounds(month()),v=C.visitsFor(state(),{from,to}),pending=state().visits.filter(v=>v.review==='submitted'),planned=state().clients.reduce((n,c)=>n+C.monthlyPlan(c,month()).hours,0),approved=v.filter(v=>v.review==='approved');
  return pageHeader('Diena, kurioje viskas aišku','Stebėkite pagalbos eigą, patikrinkite įrašus ir pasiruoškite mėnesio uždarymui.',button(icon('people')+' Asistento aplinka','worker-demo','','primary'))+`<div class="welcome"><div><span class="badge mint">${new Date().toLocaleDateString('lt-LT',{month:'long',day:'numeric',weekday:'long'})}</span><h2>Pagalba žmogui.<br>Aiškumas komandai.</h2><p>Vizitai, valandos ir paslaugos dokumentai vienoje vietoje.</p><div class="actions">${button('Peržiūrėti vizitų planą '+icon('arrow'),'nav','calendar','white')}${button('Suformuoti mėnesio aktą','new-act','','ghost-light')}</div></div><div class="welcome-visual" aria-hidden="true"><div class="orbit"></div><div class="float-card"><span class="avatar mint">${icon('check')}</span><div><b>Paslaugos užfiksuotos</b><small>Pradžia · pabaiga · patvirtinimas</small></div></div><div class="float-mini">${icon('clock')} <b>${fh(C.sumMinutes(approved))}</b><span>patikrintų valandų šį mėnesį</span></div></div></div>`+
    stats([['Suteikta valandų',fh(C.sumMinutes(v)),`Mėnesio planas ${planned.toLocaleString('lt-LT')} val.`,'clock'],['Laukia patikros',pending.length,'Suteiktų paslaugų įrašai','visits','warm'],['Aktyvūs gavėjai',state().clients.filter(c=>C.activeOn(c,day())).length,`${state().assistants.filter(a=>a.active).length} asistentai komandoje`,'people'],['Taisymų prašymai',state().requests.filter(r=>r.status==='pending').length,'Reikia koordinatoriaus sprendimo','check']])+`<div class="columns"><section class="panel"><div class="panel-head"><h2>Mėnesio valandų kontrolė</h2>${badge(month())}</div>${state().clients.map(c=>{const p=C.monthlyPlan(c,month()),mins=C.sumMinutes(v.filter(v=>v.client===c.id)),used=mins/60,pct=p.hours?Math.min(100,used/p.hours*100):0;return `<div class="usage-row"><div><b>${e(c.name)}</b><small>${e(an(c.assistant))}${p.partial?' · dalinis mėnuo':''}</small></div><span>${fh(mins)} / ${p.hours} val.</span><div class="progress"><i style="width:${pct}%" class="${used>p.hours?'over':''}"></i></div></div>`;}).join('')}</section><section class="panel"><div class="panel-head"><h2>Reikia dėmesio</h2>${icon('bell')}</div><div class="task-list">${button(`<span>${icon('visits')}<b>${pending.length} įrašai laukia patikros</b></span>${icon('arrow')}`,'nav','visits','task')}${button(`<span>${icon('check')}<b>${state().requests.filter(r=>r.status==='pending').length} taisymų prašymai</b></span>${icon('arrow')}`,'nav','requests','task')}${button(`<span>${icon('bell')}<b>${reminderRows().length} artėjantys terminai</b></span>${icon('arrow')}`,'nav','reminders','task')}</div><div class="mini-note">${icon('shield')} Valandos ir dokumentai tikrinami prieš mėnesio uždarymą.</div></section></div>`;
}
function workerPicker(){return `<form class="worker-picker"><label>Demonstracijos asistentas <select id="worker-select">${assistantOptions(worker,null)}</select></label></form>`;}
function mine(){
  const own=state().clients.filter(c=>c.assistant===worker),running=state().visits.find(v=>v.assistant===worker&&!v.endISO),myplans=state().schedule.filter(p=>p.assistant===worker&&p.date===day()&&p.status!=='cancelled');
  return pageHeader('Mano diena','Planuokite atvykimą, užfiksuokite suteiktą pagalbą ir suformuokite aktą.',workerPicker())+(running?notice(`<b>Vyksta vizitas pas ${e(cn(running.client))}</b> nuo ${time(running.startISO)}. ${button('Užbaigti vizitą','finish',running.id,'primary')}`):'')+`<div class="section-title"><h2>Šiandienos planas</h2>${button(icon('plus')+' Planuoti vizitą','new-plan','','primary')}</div>${myplans.length?`<div class="today-plans">${myplans.map(planCard).join('')}</div>`:empty('Šiandien planų nėra','Galite suplanuoti atvykimą arba pradėti neplanuotą vizitą.')}<div class="section-title"><h2>Mano paslaugos gavėjai</h2>${badge(own.length+' gavėjai')}</div><div class="client-grid">${own.map(c=>{const p=C.monthlyPlan(c,month()),mins=C.sumMinutes(C.visitsFor(state(),{client:c.id,from:month()+'-01',to:C.monthBounds(month())[1]}));return `<article class="client-card"><div class="client-top"><span class="avatar lg">${e(c.name.split(' ').map(x=>x[0]).join(''))}</span>${C.activeOn(c,day())?badge('Galiojantis sprendimas','green'):badge('Galiojimas pasibaigęs','red')}</div><h3>${e(c.name)}</h3><p>${e(c.address)}</p><small>${e(c.phone)}</small><div class="client-hours"><b>${fh(mins)}</b> iš ${p.hours} val. šį mėnesį<div class="progress"><i style="width:${p.hours?Math.min(100,mins/60/p.hours*100):0}%"></i></div></div><div class="chips">${C.allowedActivities(state(),c).map(a=>badge(a.name)).join('')}</div><div class="actions">${button('Pradėti vizitą','start',c.id,'primary',running||!C.activeOn(c,day())?'disabled':'')}${button('Planuoti','plan-client',c.id)}${button('Formuoti aktą','act-client',c.id,'link')}</div></article>`;}).join('')}</div>`;
}
function planCard(p){const own=actor().role==='assistant'&&p.assistant===worker,missed=p.status==='planned'&&p.date<day(),reassigned=state().clients.find(c=>c.id===p.client)?.assistant!==p.assistant;return `<article class="plan-card ${missed?'missed':''}"><div class="plan-time">${e(p.time)}</div><b>${e(cn(p.client))}</b><small>${e(an(p.assistant))}</small><div>${missed?badge('Neįvykdytas planas','red'):status(p.status)}${reassigned?badge('Gavėjas priskirtas kitam asistentui','amber'):''}</div>${p.note?`<p>${e(p.note)}</p>`:''}${p.cancelReason?`<p>Priežastis: ${e(p.cancelReason)}</p>`:''}<div class="actions">${own&&p.status==='planned'?button('Pradėti','start-plan',p.id,'primary',p.date!==day()||reassigned?'disabled title="Perkelkite planą į šiandieną arba pradėkite neplanuotą vizitą"':'')+(!reassigned?button('Perkelti','edit-plan',p.id,'link'):'')+button('Atšaukti','cancel-plan',p.id,'link'):''}${p.visitId?button('Faktinis vizitas','visit',p.visitId,'link'):''}</div></article>`;}
function calendar(){const d=new Date(week+'T12:00:00'),dow=(d.getDay()+6)%7;d.setDate(d.getDate()-dow);const days=Array.from({length:7},(_,i)=>C.localDay(new Date(d.getFullYear(),d.getMonth(),d.getDate()+i)));const f=q.calendar||{};return pageHeader('Vizitų planas','Planuojama vizito diena ir atvykimo laikas. Planuojamos trukmės nurodyti nereikia.',actor().role==='assistant'?button(icon('plus')+' Planuoti vizitą','new-plan','','primary'):'')+`<div class="toolbar"><div class="actions">${button('←','week-prev')}${button('Ši savaitė','week-today')}${button('→','week-next')}<b>${days[0]} — ${days[6]}</b></div>${manager()?`<form data-filter="calendar">${sf('Asistentas','assistant',assistantOptions(f.assistant||''))}<button class="btn secondary">Filtruoti</button></form>`:workerPicker()}</div><div class="week-grid">${days.map(date=>`<section class="day-column ${date===day()?'today':''}"><header><span>${new Date(date+'T12:00:00').toLocaleDateString('lt-LT',{weekday:'short'})}</span><b>${date.slice(8)}</b></header>${state().schedule.filter(p=>p.date===date&&(actor().role!=='assistant'||p.assistant===worker)&&(!f.assistant||p.assistant===f.assistant)).sort((a,b)=>a.time.localeCompare(b.time)).map(planCard).join('')||'<p class="no-plans">Vizitų nėra</p>'}</section>`).join('')}</div>${notice('Pradėti galima tik šiandienai suplanuotą vizitą. Pasikeitus dienai, planas perkeliamas su priežastimi. Praėję neįvykdyti planai lieka matomi.')}<section class="panel"><div class="panel-head"><h2>Praėję neįvykdyti planai</h2></div>${state().schedule.filter(p=>p.status==='planned'&&p.date<day()&&(manager()||p.assistant===worker)).map(p=>`<div class="past-plan"><span>${e(p.date)} · ${e(p.time)}</span>${planCard(p)}</div>`).join('')||'<p class="muted">Praėjusių neįvykdytų planų nėra.</p>'}</section>`;}
function visitRows(list){return list.map(v=>`<tr><td><b>${e(cn(v.client))}</b><small>${e(an(v.assistant))}</small></td><td>${e(v.date)}<small>${time(v.startISO)} – ${time(v.endISO)}</small></td><td class="numeric">${v.endISO?fh(C.integerMinutes(v)):'–'}</td><td>${v.activities.map(a=>e(a.name)).join(', ')||'–'}</td><td>${status(v.review)}<small>${C.isSigned(v)?'Gavėjas patvirtino':v.noSignReason?'Užfiksuota parašo negavimo priežastis':'Gavėjo parašo nėra'}</small></td><td>${C.visitIssues(state(),v).length?badge(C.visitIssues(state(),v).length+' past.','amber'):icon('check')}</td><td>${button('Atidaryti','visit',v.id,'link')}</td></tr>`);}
function visits(){const f=q.visits||{},list=state().visits.filter(v=>(manager()||v.assistant===worker)&&(!f.search||(cn(v.client)+' '+an(v.assistant)).toLowerCase().includes(f.search.toLowerCase()))&&(!f.from||v.date>=f.from)&&(!f.to||v.date<=f.to)&&(!f.status||v.review===f.status)&&(!f.assistant||v.assistant===f.assistant)&&(!f.issues||C.visitIssues(state(),v).length)).sort((a,b)=>b.startISO.localeCompare(a.startISO));return pageHeader('Suteiktos paslaugos','Faktiniai vizitai, gavėjų patvirtinimai ir koordinatoriaus patikra.',actor().role==='assistant'?workerPicker():button(icon('download')+' Eksportuoti','visits-csv'))+`<form class="filters" data-filter="visits">${field('Paieška','search',f.search||'','search','placeholder="Gavėjas arba asistentas"')}${field('Nuo','from',f.from||'','date')}${field('Iki','to',f.to||'','date')}${sf('Būsena','status',selectOptions(['running','submitted','approved','returned'].map(id=>({id,name:statusLabels[id]})),f.status||'','Visos būsenos'))}${manager()?sf('Asistentas','assistant',assistantOptions(f.assistant||'')):''}${check('issues','Tik su pastabomis',f.issues)}<button class="btn primary">Taikyti</button>${button('Išvalyti','clear-filter','visits','link')}</form><section class="panel flush"><div class="panel-head"><h2>Vizitų registras</h2>${badge(list.length+' įrašai')}</div>${list.length?table(['Gavėjas / asistentas','Data ir laikas','Valandos','Veiklos','Būsena','Patikra',''],visitRows(list)):empty('Įrašų nėra','Pakeiskite filtrus arba užregistruokite vizitą.')}</section>${notice('Trukmė apvalinama iki artimiausios minutės vieną kartą kiekvienam vizitui. Suvestinės ir dokumentai sudedami iš tų pačių minučių.')} `;}
function requests(){const list=state().requests.filter(r=>(manager()||r.assistant===worker)&&(requestArchive?r.status!=='pending':r.status==='pending')).sort((a,b)=>b.created.localeCompare(a.created));return pageHeader('Taisymų prašymai','Asistentas prašo leidimo. Koordinatorius arba administratorius priima sprendimą.')+`<div class="tabs">${button('Laukia sprendimo','requests-pending','','tab '+(!requestArchive?'active':''))}${button('Sprendimų istorija','requests-archive','','tab '+(requestArchive?'active':''))}</div><section class="panel flush">${list.length?table(['Įrašas','Prašymas','Būsena','Sprendimas',''],list.map(r=>`<tr><td><b>${e(cn(state().visits.find(v=>v.id===r.visit)?.client))}</b><small>${e(an(r.assistant))} · v${r.rev}<br>${dt(r.created)}</small></td><td>${e(r.reason)}</td><td>${status(r.status)}</td><td>${e(r.decisionNote||'–')}<small>${dt(r.decidedAt)}</small></td><td><div class="actions">${manager()&&r.status==='pending'?button('Suteikti leidimą','request-approve',r.id,'primary')+button('Atmesti','request-reject',r.id):''}${button('Vizitas','visit',r.visit,'link')}</div></td></tr>`)):empty(requestArchive?'Sprendimų istorija tuščia':'Laukiančių prašymų nėra','Prašymas pateikiamas atidarius konkretų užbaigtą vizitą.')}</section>${notice('Leidimas galioja vienai konkretaus įrašo versijos korekcijai. Pakeitus laiką ar veiklas, senas gavėjo patvirtinimas nebegalioja ir įrašas pateikiamas pakartotinei patikrai.')} `;}
function clients(){const f=q.clients||{},list=state().clients.filter(c=>(!f.search||(c.name+' '+c.address+' '+c.contract+' '+c.decision).toLowerCase().includes(f.search.toLowerCase()))&&(!f.assistant||c.assistant===f.assistant)&&(!f.group||c.group===f.group)&&(!f.active||(f.active==='yes')===C.activeOn(c,day())));return pageHeader('Paslaugos gavėjai','Sprendimai, priskyrimai, valandų planai ir individualios leistinos veiklos.',button(icon('plus')+' Naujas gavėjas','new-client','','primary'))+`<form class="filters" data-filter="clients">${field('Paieška','search',f.search||'','search','placeholder="Vardas, adresas arba dokumento Nr."')}${sf('Asistentas','assistant',assistantOptions(f.assistant||''))}${sf('Negalios pobūdis','group',selectOptions([...new Set(state().clients.map(c=>c.group))].map(id=>({id,name:id})),f.group||'','Visos grupės'))}${sf('Galiojimas','active',selectOptions([{id:'yes',name:'Galiojantys'},{id:'no',name:'Negaliojantys'}],f.active||'','Visi'))}<button class="btn primary">Taikyti</button>${button('Išvalyti','clear-filter','clients','link')}</form><section class="panel flush">${list.length?table(['Gavėjas','Asistentas','Sprendimas','Mėnesio planas','Galiojimas',''],list.map(c=>{const p=C.monthlyPlan(c,month());return `<tr><td><b>${e(c.name)}</b><small>${e(c.address)}</small></td><td>${e(an(c.assistant))}</td><td>${e(c.decision)}<small>${e(c.decisionDate)} — ${e(c.decisionUntil)}</small></td><td><b>${p.hours} val.</b>${p.partial?'<small>Dalinis mėnuo</small>':''}</td><td>${C.activeOn(c,day())?badge('Galioja','green'):badge('Negalioja','red')}</td><td><div class="actions">${button('Kortelė','client',c.id,'link')}${button('Mokėjimo parametrai','finance',c.id,'link')}</div></td></tr>`;})):empty('Gavėjų nerasta','Pakeiskite paiešką arba filtrus.')}</section>`;}
function reportData(){const f=q.reports||{mode:'month',period:month()},mode=f.mode||'month',period=f.period||month();let from,to;if(mode==='year'){from=period.slice(0,4)+'-01-01';to=period.slice(0,4)+'-12-31';}else [from,to]=C.monthBounds(period.length===7?period:month());const cs=state().clients.filter(c=>(!f.client||c.id===f.client)&&(!f.group||c.group===f.group)&&(!f.age||c.age===f.age));const ids=cs.map(c=>c.id);const v=C.visitsFor(state(),{from,to,assistant:f.assistant||''}).filter(v=>ids.includes(v.client));const all=state().visits.filter(x=>ids.includes(x.client)&&x.date>=from&&x.date<=to&&(!f.assistant||x.assistant===f.assistant));return {f,mode,period,from,to,cs,v,all};}
function reports(){const {f,mode,period,from,to,cs,v,all}=reportData();const planHours=c=>mode==='year'?Array.from({length:12},(_,i)=>C.monthlyPlan(c,from.slice(0,4)+'-'+String(i+1).padStart(2,'0')).hours).reduce((a,b)=>a+b,0):C.monthlyPlan(c,from.slice(0,7)).hours;return pageHeader('Ataskaitos','Mėnesio ir metų rezultatai pagal gavėją, asistentą ir paslaugos laikotarpį.',button(icon('download')+' Excel (CSV)','reports-csv')+button('Spausdinti / PDF','reports-print'))+`<form class="filters" data-filter="reports">${sf('Laikotarpis','mode',selectOptions([{id:'month',name:'Mėnuo'},{id:'year',name:'Metai'}],mode,null))}${field('Mėnuo / metai','period',period,'text','pattern="[0-9]{4}(-[0-9]{2})?" placeholder="2026-10 arba 2026"')}${sf('Gavėjas','client',selectOptions(state().clients,f.client||'','Visi gavėjai'))}${sf('Asistentas','assistant',assistantOptions(f.assistant||''))}${sf('Negalios pobūdis','group',selectOptions([...new Set(state().clients.map(c=>c.group))].map(id=>({id,name:id})),f.group||'','Visos grupės'))}${sf('Amžius','age',selectOptions([...new Set(state().clients.map(c=>c.age))].map(id=>({id,name:id})),f.age||'','Visos grupės'))}<button class="btn primary">Rodyti</button></form>`+stats([['Faktinės valandos',fh(C.sumMinutes(v)),`${from} — ${to}`,'clock'],['Patikrintos valandos',fh(C.sumMinutes(v.filter(x=>x.review==='approved'))),'Koordinatoriaus patikra','check'],['Gavėjo patvirtintos',fh(C.sumMinutes(v.filter(C.isSigned))),'Galiojantis vizito parašas','shield'],['Vizitai su pastabomis',all.filter(x=>C.visitIssues(state(),x).length).length,'Įskaitant neužbaigtus vizitus','bell']])+`${all.some(x=>!x.endISO)?notice('Laikotarpiu yra '+all.filter(x=>!x.endISO).length+' neužbaigti vizitai. Jų valandos į suvestinės sumą ir dokumentus dar neįtrauktos.','warn'):''}<section class="panel flush"><div class="panel-head"><h2>Gavėjų suvestinė</h2>${f.assistant?badge('Planas rodomas gavėjui, ne asistentui') :''}</div>${table(['Gavėjas','Paskirta val.','Faktiškai val.','Patikrinta val.','Gavėjo patv. val.','Likutis val.'],cs.map(c=>{const r=v.filter(v=>v.client===c.id),p=planHours(c);return `<tr><td><b>${e(c.name)}</b></td><td class="numeric">${p.toLocaleString('lt-LT')}</td><td class="numeric">${fh(C.sumMinutes(r))}</td><td class="numeric">${fh(C.sumMinutes(r.filter(v=>v.review==='approved')))}</td><td class="numeric">${fh(C.sumMinutes(r.filter(C.isSigned)))}</td><td class="numeric ${p*60<C.sumMinutes(r)?'text-red':''}">${fh(p*60-C.sumMinutes(r))}</td></tr>`;}))}</section><section class="panel flush"><div class="panel-head"><h2>Pagal asistentą</h2></div>${table(['Asistentas','Vizitai','Faktiškai val.','Patikrinta val.'],state().assistants.filter(a=>!f.assistant||a.id===f.assistant).map(a=>{const r=v.filter(v=>v.assistant===a.id);return `<tr><td>${e(a.name)}</td><td>${r.length}</td><td class="numeric">${fh(C.sumMinutes(r))}</td><td class="numeric">${fh(C.sumMinutes(r.filter(v=>v.review==='approved')))}</td></tr>`;}))}</section>${notice('Daliniam galiojimo mėnesiui taikomas sprendime nurodytas mėnesio limitas, be automatinio proporcinio perskaičiavimo. Negaliojantiems mėnesiams valandos neskiriamos.')} `;}
function documents(type){const list=C.visibleDocs(state(),actor(),type).sort((a,b)=>b.created.localeCompare(a.created)),payment=type==='payments';return pageHeader(payment?'Mokėjimo pranešimai':'Faktiškai suteiktų paslaugų aktai',payment?'Pagal pateiktą šabloną. Gavėjas ir paslaugos teikėjas pasirašo atspausdintą dokumentą.':'Pasirinktas laikotarpis, faktinė pradžia ir pabaiga, valandų suma bei paslaugų kokybės vertinimas.',button(icon('plus')+' '+(payment?'Formuoti pranešimą':'Formuoti aktą'),payment?'new-payment':'new-act','','primary'))+(actor().role==='assistant'?notice('Galite formuoti aktą tik iš savo suteiktų paslaugų, įskaitant ankstesnius vizitus pas vėliau kitam asistentui priskirtą gavėją.'):'')+`<section class="panel flush">${list.length?table(['Dokumentas','Gavėjas / laikotarpis','Valandos',payment?'Mokėti':'Asistentas','Būsena',''],list.map(d=>`<tr><td><b>${e(d.number)} · v${d.version||1}</b><small>${e(d.issuedDate)}</small></td><td><b>${e(d.name)}</b><small>${e(d.from)} — ${e(d.to)}</small></td><td class="numeric">${fh(d.minutes??Math.round((d.totalHours||d.total||0)*60))}</td><td>${payment?money(d.paid??d.data?.paid*100)+' Eur':e(d.assistant?an(d.assistant):'Visi laikotarpio asistentai')}</td><td>${C.staleDocument(state(),d)?badge('Duomenys pasikeitė','red'):status(d.status)}</td><td>${button('Peržiūrėti','doc-view',d.id,'link',`data-type="${type}"`)}</td></tr>`)):empty(payment?'Mokėjimo pranešimų dar nėra':'Paslaugų aktų dar nėra',payment?'Pasirinkite gavėją ir mėnesį. Parametrai paimami iš jo kortelės.':'Įveskite laikotarpio pradžią ir pabaigą. Vizitų laikai bei valandos bus įrašyti automatiškai.')}</section>${notice('Projektas arba pasenusi dokumento versija spausdinama su aiškia žyma. Galutinį dokumentą po peržiūros patvirtina koordinatorius arba administratorius. Mėnesio dokumentuose paliktos tuščios rankinių parašų ir datų vietos.')} `;}
function reminderRows(){const end=new Date();end.setDate(end.getDate()+Number(state().settings.days));const until=C.localDay(end),rows=[];for(const c of state().clients)for(const [key,label]of [['contractUntil','Sutartis'],['decisionUntil','Savivaldybės sprendimas'],['disabilityUntil','Negalios dokumentas']])if(c[key]&&c[key]<=until)rows.push({client:c,key,label,date:c[key],overdue:c[key]<day()});return rows.sort((a,b)=>a.date.localeCompare(b.date));}
function reminders(){return pageHeader('Galiojimo priminimai',`Artėjantys terminai per ${state().settings.days} dienų ir jau pasibaigę dokumentai.`)+`<section class="panel flush">${reminderRows().length?table(['Gavėjas','Dokumentas','Galioja iki','Būsena',''],reminderRows().map(r=>`<tr><td><b>${e(r.client.name)}</b></td><td>${r.label}</td><td>${e(r.date)}</td><td>${badge(r.overdue?'Pasibaigęs':'Artėja pabaiga',r.overdue?'red':'amber')}</td><td>${button('Atidaryti kortelę','client',r.client.id,'link')}${button('Priminimo demonstracija','remind',r.client.id+':'+r.key,'link')}</td></tr>`)):empty('Artėjančių terminų nėra','Sistema tikrina sutarties, sprendimo ir negalios dokumento galiojimą.')}</section>${notice('El. pašto siuntimas šioje demonstracijoje imituojamas. Primintų dokumentų įrašai matomi veiksmų istorijoje.')} `;}
function activities(){const f=q.activities||{},list=state().activities.filter(a=>(!f.search||a.name.toLowerCase().includes(f.search.toLowerCase()))&&(!f.active||String(a.active)===f.active));return pageHeader('Leistinų veiklų katalogas','Administratorius sukuria veiklas. Gavėjo kortelėje pažymimos konkrečiam žmogui leistinos veiklos.',button(icon('plus')+' Nauja veikla','new-activity','','primary'))+`<form class="filters" data-filter="activities">${field('Paieška','search',f.search||'','search')}${sf('Būsena','active',selectOptions([{id:'true',name:'Aktyvios'},{id:'false',name:'Neaktyvios'}],f.active||'','Visos'))}<button class="btn primary">Taikyti</button></form><section class="panel flush">${table(['Veikla','Priskirta gavėjams','Būsena',''],list.map(a=>`<tr><td><b>${e(a.name)}</b></td><td>${state().clients.filter(c=>c.allowed.includes(a.id)).length}</td><td>${badge(a.active?'Aktyvi':'Neaktyvi',a.active?'green':'neutral')}</td><td>${button('Redaguoti','activity',a.id,'link')}${button(a.active?'Išjungti':'Aktyvuoti','activity-toggle',a.id,'link')}</td></tr>`))}</section>${notice('Pervadinus ar išjungus veiklą, anksčiau suteiktų paslaugų įrašai ir dokumentai išlaiko tuo metu užfiksuotą pavadinimą. Išjungtos veiklos naujai pažymėti negalima.')} `;}
function assistants(){const f=q.assistants||{},list=state().assistants.filter(a=>!f.search||(a.name+' '+a.email).toLowerCase().includes(f.search.toLowerCase()));return pageHeader('Asistentai','Komanda, paskyrų aktyvumas ir gavėjų priskyrimai.',button(icon('plus')+' Naujas asistentas','new-assistant','','primary'))+`<form class="filters" data-filter="assistants">${field('Paieška','search',f.search||'','search')}<button class="btn primary">Ieškoti</button></form><section class="panel flush">${table(['Asistentas','El. paštas','Priskirti gavėjai','Būsena',''],list.map(a=>`<tr><td><b>${e(a.name)}</b></td><td>${e(a.email)}</td><td>${state().clients.filter(c=>c.assistant===a.id).length}</td><td>${badge(a.active?'Aktyvus':'Neaktyvus',a.active?'green':'neutral')}</td><td>${button('Redaguoti','assistant',a.id,'link')}</td></tr>`))}</section>${notice('Rolės perjungiklis yra demonstravimo priemonė. Tikras prisijungimas ir prieigos tikrinimas serveryje įgyvendinami produkcinėje sistemoje.')} `;}
function importView(){return pageHeader('Pradinių registrų importas','Pirmiausia patikrinamos visos eilutės. Jei randama klaidų, neįrašomas nė vienas pakeitimas.')+`<section class="panel"><div class="section-title"><h2>1. Pasiruoškite failą</h2><div class="actions">${button('Gavėjų CSV šablonas','template-clients')}${button('Asistentų CSV šablonas','template-assistants')}</div></div><p>CSV failas su kabliataškiais, UTF-8 koduote. Vienu kartu iki 500 įrašų. Gavėjų veiklos atskiriamos simboliu <b>|</b>. Atnaujinimas atpažįstamas pagal <b>id</b>.</p><form id="import-form" class="form-grid">${sf('Registras','kind',selectOptions([{id:'clients',name:'Paslaugos gavėjai'},{id:'assistants',name:'Asistentai'}],importPreview?.kind||'clients',null))}<label class="field">CSV failas<input type="file" name="file" accept=".csv,text/csv" required></label><button class="btn primary">2. Patikrinti ir peržiūrėti</button></form></section>${importPreview?`<section class="panel"><h2>3. Importo peržiūra</h2>${importPreview.errors.length?notice(importPreview.errors.map(e).join('<br>'),'warn'):notice('Patikra sėkminga. Galite vienu veiksmu įrašyti visą rinkinį.')} ${importPreview.changes.length?table(['ID','Pavadinimas','Veiksmas'],importPreview.changes.map(c=>`<tr><td>${e(c.id)}</td><td>${e(c.name)}</td><td>${e(c.type)}</td></tr>`)):''}<div class="actions">${button('Importuoti visus įrašus','apply-import','','primary',importPreview.errors.length?'disabled':'')}${button('Atšaukti','cancel-import')}</div></section>`:''}`;}
function audit(){const f=q.audit||{},list=state().audit.filter(x=>!f.search||(x.action+' '+x.target+' '+x.user).toLowerCase().includes(f.search.toLowerCase()));return pageHeader('Veiksmų istorija','Kas, kada ir kokį veiksmą atliko demonstracijoje.',button(icon('download')+' Eksportuoti CSV','audit-csv'))+`<form class="filters" data-filter="audit">${field('Paieška','search',f.search||'','search')}<button class="btn primary">Ieškoti</button></form><section class="panel flush">${list.length?table(['Laikas','Naudotojas','Veiksmas','Objektas'],list.slice(0,300).map(x=>`<tr><td>${dt(x.at)}</td><td>${e(roleNames[x.user]||an(x.user))}</td><td>${e(x.action)}</td><td>${e(x.target)}</td></tr>`)):empty('Veiksmų dar nėra','Pakeitimai ir patvirtinimai bus registruojami čia.')}</section>${notice('Tai vietinė demonstracijos istorija. Nekeičiamas serverio auditas, centralizuotos atsarginės kopijos ir incidentų valdymas yra produkcinio sprendimo dalis.')} `;}
function settings(){return pageHeader('Demonstracijos nustatymai','Pasirenkamos funkcijos, duomenų kopija ir perkėlimas.')+`<div class="columns"><section class="panel"><h2>Funkcijų parinktys</h2><form id="settings-form" class="form-grid">${field('Priminimas prieš, dienų','days',state().settings.days,'number','min="1" max="365" required')}${field('Valandų įspėjimo slenkstis, %','threshold',state().settings.threshold,'number','min="1" max="100" required')}<div class="full">${check('offline','Leisti darbą be interneto (pasirenkamas modulis)',state().settings.offline)}${check('gps','Rodyti vietos fiksavimo scenarijų (demonstracija)',state().settings.gps)}</div><button class="btn primary">Išsaugoti nustatymus</button></form><p class="muted">Viršijus valandų limitą rodomas įspėjimas. Faktinis suteiktas laikas neprarandamas. Patikrą ir sprendimą priima koordinatorius.</p></section><section class="panel"><h2>Duomenys ir perdavimas</h2><p>Pilna JSON kopija išsaugo registrus, vizitų versijas, parašų taškus, dokumentus ir veiksmų istoriją.</p><div class="stack">${button(icon('download')+' Eksportuoti pilną JSON kopiją','backup','','primary')}${button('Atkurti iš JSON kopijos','restore')}${button('Atsisiųsti HTML su esamais demo duomenimis','html-download')}${button('Atkurti pradinius demo duomenis','reset','','danger')}</div><p class="muted">Duomenys saugomi šios naršyklės atmintyje. Kopiją reikia išsisaugoti atskirai.</p></section></div>${notice('Demonstracijoje nėra bendros serverio duomenų bazės. Ryšio atkūrimas parodo siuntimo eilės eigą, tačiau duomenys į kitus įrenginius neperduodami. Naudokite pavyzdinius duomenis.')} `;}
function modal(title,body,{submitLabel='Išsaugoti',submit=null,wide=false}={}){
  const d=$('#modal');if(d.open)d.close();d.className=wide?'wide':'';d.innerHTML=`<form id="modal-form"><header class="modal-header"><div><div class="eyebrow">SPIC · ASMENINĖ PAGALBA</div><h2>${title}</h2></div><button type="button" class="icon-btn" data-action="close" aria-label="Uždaryti">×</button></header><div class="modal-body">${body}<div id="form-error" class="form-error" role="alert" hidden></div></div><footer class="modal-footer">${button(submit?'Atšaukti':'Uždaryti','close')}${submit?`<button class="btn primary" type="submit">${submitLabel}</button>`:''}</footer></form>`;
  d.showModal();$('#modal-form').onsubmit=ev=>{ev.preventDefault();if(!submit)return;const btn=ev.submitter;try{btn.disabled=true;submit(new FormData(ev.target));d.close();render();toast('Išsaugota.');}catch(error){$('#form-error').hidden=false;$('#form-error').textContent=error.message;}finally{btn.disabled=false;}};
}
function reasonModal(title,onSubmit,label='Priežastis / komentaras'){modal(title,textarea(label,'reason','','required'),{submit:data=>onSubmit(data.get('reason'))});}
function scheduleForm(id='',cid=''){const p=state().schedule.find(p=>p.id===id);modal(p?'Perkelti suplanuotą vizitą':'Suplanuoti vizitą',`<div class="form-grid">${p?notice(`Ankstesnis atvykimas: <b>${e(p.date)} ${e(p.time)}</b>`):''}${sf('Paslaugos gavėjas','client',clientOptions(p?.client||cid))}${field('Diena','date',p?.date>=day()?p.date:day(),'date',`min="${day()}" required`)}${field('Atvykimo laikas','time',p?.time||'09:00','time','required')}${textarea('Pastaba','note',p?.note||'')}${p?textarea('Perkėlimo priežastis','reason','','required'):''}</div><p class="muted">Planuojamos pabaigos ir trukmės žymėti nereikia.</p>`,{submit:d=>app.scheduleSave({id,client:d.get('client'),date:d.get('date'),time:d.get('time'),note:d.get('note'),reason:d.get('reason')})});}
function showVisit(id){const v=state().visits.find(v=>v.id===id);C.assert(v&&(manager()||v.assistant===worker),'Įrašas nepasiekiamas.');const p=state().schedule.find(p=>p.id===v.planId),issues=C.visitIssues(state(),v),own=actor().role==='assistant'&&v.assistant===worker;modal('Vizitas · '+e(cn(v.client)),`<div class="detail-meta">${status(v.review)}${badge('Versija '+v.rev)}<span>${e(an(v.assistant))}</span></div><div class="detail-grid"><div><small>Faktinė pradžia</small><b>${dt(v.startISO)}</b></div><div><small>Faktinė pabaiga</small><b>${dt(v.endISO)}</b></div><div><small>Suteikta valandų</small><b>${v.endISO?fh(C.integerMinutes(v)):'Vyksta'}</b></div><div><small>Planuotas atvykimas</small><b>${p?e(p.date)+' '+e(p.time):'Neplanuotas vizitas'}</b></div></div><h3>Suteiktos veiklos</h3><div class="chips">${v.activities.map(a=>badge(a.name)).join('')||'Dar nepažymėta'}</div><p>${e(v.note||'Pastabų nėra.')}</p>${issues.length?notice(issues.map(e).join('<br>'),'warn'):''}${v.returnReason?notice('Grąžinimo priežastis: '+e(v.returnReason),'warn'):''}<h3>Gavėjo patvirtinimas</h3>${C.isSigned(v)?`<div class="signature-box">${signatureSVG(v.confirmation)}<span>${e(v.confirmation.name)} · ${dt(v.confirmation.at)} · v${v.confirmation.rev}${v.confirmation.demo?' · demonstracinis patvirtinimas':''}</span></div>`:v.noSignReason?`<p>${e(v.noSignReason)}</p>`:'<p class="muted">Patvirtinimas dar negautas.</p>'}<div class="actions wrap">${own&&!v.endISO?button('Užbaigti vizitą','finish',id,'primary'):''}${own&&v.endISO&&v.review!=='approved'?button(C.isSigned(v)?'Atnaujinti parašą':'Gavėjo patvirtinimas','sign',id,'primary'):''}${own&&v.endISO?(C.canEditVisit(state(),actor(),v)?button('Taisyti įrašą','edit-visit',id,'primary'):button('Prašyti leidimo taisyti','request',id)):''}${manager()&&v.endISO?button('Patikrinti įrašą','approve-visit',id,'primary',issues.length||v.review==='approved'?'disabled':'')+button('Grąžinti taisyti','return-visit',id):''}</div><h3>Versijų istorija</h3>${v.versions.length?table(['Versija / pakeitimas','Buvo','Dabar'],[...v.versions].reverse().map((old,i)=>{const next=v.versions.find(x=>x.rev===old.rev+1)||v;return `<tr><td><b>v${old.rev} → v${next.rev}</b><small>${dt(old.changedAt)} · ${e(an(old.changedBy))}</small>${e(old.changeReason)}</td><td>${dt(old.startISO)} — ${dt(old.endISO)}<small>${old.activities.map(a=>e(a.name)).join(', ')}<br>${e(old.note)}</small></td><td>${dt(next.startISO)} — ${dt(next.endISO)}<small>${next.activities.map(a=>e(a.name)).join(', ')}<br>${e(next.note)}</small></td></tr>`;})):'<p class="muted">Įrašas dar nebuvo koreguotas.</p>'}`,{wide:true});}
function signatureSVG(c){if(c.demo)return '<div class="demo-signature">Demonstracinis patvirtinimas</div>';return `<svg class="saved-signature" viewBox="0 0 600 160" role="img" aria-label="Gavėjo parašas">${(c.strokes||[]).map(line=>`<polyline fill="none" stroke="#172f37" stroke-width="2.4" stroke-linecap="round" points="${line.map(p=>`${Number(p.x)},${Number(p.y)}`).join(' ')}"/>`).join('')}</svg>`;}
function finishForm(id){const v=state().visits.find(v=>v.id===id),c=state().clients.find(c=>c.id===v.client),acts=C.allowedActivities(state(),c);modal('Užbaigti vizitą · '+e(c.name),`<div class="detail-grid"><div><small>Pradžia</small><b>${dt(v.startISO)}</b></div><div><small>Pabaiga</small><b>Fiksuojama paspaudus „Užbaigti“</b></div></div><h3>Kokias paslaugas suteikėte?</h3><div class="checkbox-grid">${acts.map(a=>check('activities',e(a.name),false,a.id)).join('')}</div>${textarea('Vizito pastaba','note',v.note)}`,{submitLabel:'Užbaigti vizitą',submit:d=>app.finishVisit(id,d.getAll('activities'),d.get('note'))});}
function signForm(id){const v=state().visits.find(v=>v.id===id);let strokes=[],active=null;modal('Gavėjo patvirtinimas',`<p>Patvirtinu, kad ${e(v.date)} asmeninės pagalbos paslaugos suteiktos: <b>${fh(C.integerMinutes(v))} val.</b></p>${field('Pasirašančio gavėjo / atstovo vardas, pavardė','name',cn(v.client),'text','required')}<canvas id="sign-canvas" width="600" height="160" aria-label="Pasirašykite čia"></canvas><div class="actions">${button('Išvalyti parašą','clear-sign')}</div><hr>${textarea('Jei pasirašyti nepavyko – priežastis (tuomet parašas nebūtinas)','reason',v.noSignReason)}<p class="muted">Patvirtinimas siejamas tik su vizito v${v.rev}. Tai parašas ekrane, be kvalifikuoto elektroninio parašo integracijos.</p>`,{submitLabel:'Išsaugoti patvirtinimą',submit:d=>app.signVisit(id,{name:d.get('name'),reason:d.get('reason'),strokes})});
  const canvas=$('#sign-canvas'),ctx=canvas.getContext('2d');ctx.lineWidth=2.4;ctx.lineCap='round';ctx.strokeStyle='#172f37';
  const point=ev=>{const r=canvas.getBoundingClientRect();return {x:(ev.clientX-r.left)/r.width*600,y:(ev.clientY-r.top)/r.height*160};};
  canvas.onpointerdown=ev=>{canvas.setPointerCapture(ev.pointerId);active=[];strokes.push(active);active.push(point(ev));};canvas.onpointermove=ev=>{if(!active)return;const p=point(ev),last=active.at(-1);ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(p.x,p.y);ctx.stroke();active.push(p);};canvas.onpointerup=canvas.onpointercancel=()=>active=null;
  $('[data-action="clear-sign"]').onclick=()=>{strokes=[];ctx.clearRect(0,0,600,160);};
  // Priežastį galima pateikti ir be vardo / parašo.
  $('#modal-form [name="reason"]').oninput=ev=>$('#modal-form [name="name"]').required=!ev.target.value.trim();
}
function localInput(iso){const d=new Date(iso);return C.localDay(d)+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');}
function editVisit(id){const v=state().visits.find(v=>v.id===id),c=state().clients.find(c=>c.id===v.client),acts=[...new Map([...v.activities,...C.allowedActivities(state(),c)].map(a=>[a.id,a])).values()];modal('Taisyti vizitą · v'+v.rev,notice('Išsaugojus bus sukurta nauja versija. Reikės iš naujo gauti gavėjo patvirtinimą ir pateikti koordinatoriaus patikrai.','warn')+`<div class="form-grid">${field('Faktinė pradžia','start',localInput(v.startISO),'datetime-local','required')}${field('Faktinė pabaiga','end',localInput(v.endISO),'datetime-local','required')}<div class="full checkbox-grid">${acts.map(a=>check('activities',e(a.name),v.activities.some(x=>x.id===a.id),a.id)).join('')}</div>${textarea('Pastaba','note',v.note)}${textarea('Pakeitimo priežastis','reason','','required')}</div>`,{submitLabel:'Pateikti naują versiją',submit:d=>app.editVisit(id,{startISO:new Date(d.get('start')).toISOString(),endISO:new Date(d.get('end')).toISOString(),activities:d.getAll('activities'),note:d.get('note'),reason:d.get('reason')})});}
function clientForm(id=''){const old=state().clients.find(c=>c.id===id),c=old||{allowed:[],plans:[],finance:[]},p=[...(c.plans||[])].sort((a,b)=>a.from.localeCompare(b.from)).at(-1);modal(old?'Gavėjo kortelė · '+e(c.name):'Naujas paslaugos gavėjas',`<div class="form-grid">${field('Vardas, pavardė','name',c.name,'text','required')}${sf('Priskirtas asistentas','assistant',selectOptions(state().assistants.filter(a=>a.active||a.id===c.assistant),c.assistant||'',null))}${field('Adresas','address',c.address,'text','required')}${field('Telefonas','phone',c.phone,'tel')}${field('Kontaktinis asmuo / atstovas','contact',c.contact)}${field('Negalios pobūdis','group',c.group||'Judėjimo','text','list="disability-groups"')}<datalist id="disability-groups">${['Judėjimo','Regos','Klausos','Intelekto','Psichosocialinė','Kompleksinė'].map(x=>`<option value="${x}">`).join('')}</datalist>${sf('Amžiaus grupė','age',selectOptions(['0–17','18–64','65+'].map(id=>({id,name:id})),c.age||'18–64',null))}${field('Negalios dokumentas galioja iki','disabilityUntil',c.disabilityUntil,'date')}<h3 class="full">Sutartis ir savivaldybės sprendimas</h3>${field('Sutarties Nr.','contract',c.contract,'text','required')}${field('Sutartis nuo','contractFrom',c.contractFrom||day(),'date')}${field('Sutartis iki','contractUntil',c.contractUntil,'date','required')}${field('Sprendimo Nr.','decision',c.decision,'text','required')}${field('Sprendimas nuo','decisionDate',c.decisionDate||day(),'date','required')}${field('Sprendimas iki','decisionUntil',c.decisionUntil,'date','required')}<h3 class="full">Mėnesio valandų planas</h3>${p?`<div class="full">${table(['Nuo mėnesio','Valandos'],[...c.plans].sort((a,b)=>a.from.localeCompare(b.from)).map(p=>`<tr><td>${e(p.from)}</td><td>${e(p.hours)}</td></tr>`))}</div>`:''}${field('Plano galiojimo pradžia','planFrom',p?.from||month(),'month','required')}${field('Valandos per mėnesį','hours',p?.hours||0,'number','min="0" max="744" step="0.01" required')}<p class="muted full">Pakeitimą kitam laikotarpiui įrašykite su nauju pradžios mėnesiu. Ankstesni planai išsaugomi.</p><h3 class="full">Gavėjui leidžiamos veiklos</h3><div class="full checkbox-grid">${state().activities.filter(a=>a.active||c.allowed.includes(a.id)).map(a=>check('allowed',e(a.name)+(a.active?'':' <small>(neaktyvi)</small>'),c.allowed.includes(a.id),a.id)).join('')}</div>${textarea('Pastaba','note',c.note)}${old?notice('Keičiant asistentą, istorinių vizitų autorystė ir ankstesni aktai išlieka. Buvusio asistento neįvykdyti planai neperduodami automatiškai — juos reikia atšaukti ir suplanuoti iš naujo.','warn'):''}</div>`,{wide:true,submit:d=>{const plans=C.clone(c.plans);const plan={from:d.get('planFrom'),hours:Number(d.get('hours'))};const input={...C.clone(c),id,plans:[...plans.filter(p=>p.from!==plan.from),plan],allowed:d.getAll('allowed')};for(const k of ['name','assistant','address','phone','contact','group','age','disabilityUntil','contract','contractFrom','contractUntil','decision','decisionDate','decisionUntil','note'])input[k]=d.get(k);app.clientSave(input);}});}
function currentFinance(c,m=month()){return (c.finance||[]).filter(t=>t.from<=m).sort((a,b)=>a.from.localeCompare(b.from)).at(-1);}
const ruleNames={manual:'Koordinatoriaus nustatyta mėnesio suma',comp20:'Kompensacijos 20 % (demonstracinė taisyklė)',comp30:'Kompensacijos 30 % (demonstracinė taisyklė)'};
function financeForm(id){const c=state().clients.find(c=>c.id===id),f=currentFinance(c)||{from:month(),rate:12.13,comp:0,contribution:0,rule:'manual'};modal('Mokėjimo parametrai · '+e(c.name),notice('Tai gavėjui ir laikotarpiui skirti parametrai. Skaičiavimo pavyzdys turi būti patikrintas pagal SPIC patvirtintą tvarką. Neturint patvirtintos taisyklės, įrašoma koordinatoriaus nustatyta mėnesio suma.')+`<div class="form-grid">${field('Galioja nuo mėnesio','from',f.from,'month','required')}${field('Paslaugos įkainis, Eur / val.','rate',f.rate,'number','min="0" step="0.01" required')}${sf('Skaičiavimo būdas','rule',selectOptions(Object.entries(ruleNames).map(([id,name])=>({id,name})),f.rule,null))}${field('Individualios pagalbos kompensacija, Eur','comp',f.comp,'number','min="0" step="0.01" required')}${field('Nustatyta gavėjo suma, Eur (rankiniam būdui)','contribution',f.contribution,'number','min="0" step="0.01" required')}${textarea('Pagrindas / pastaba','note',f.note)}</div><h3>Galiojimo istorija</h3>${(c.finance||[]).length?table(['Nuo','Įkainis','Skaičiavimo būdas'],c.finance.map(x=>`<tr><td>${e(x.from)}</td><td>${Number(x.rate).toFixed(2)} Eur</td><td>${e(ruleNames[x.rule])}</td></tr>`)):'<p>Parametrų dar nėra.</p>'}`,{wide:true,submit:d=>app.financeSave(id,{from:d.get('from'),rate:Number(d.get('rate')),comp:Number(d.get('comp')),contribution:Number(d.get('contribution')),rule:d.get('rule'),note:d.get('note')})});}
function activityForm(id=''){const a=state().activities.find(a=>a.id===id);modal(a?'Redaguoti veiklą':'Nauja leistina veikla',field('Veiklos pavadinimas','name',a?.name||'','text','required maxlength="150"'),{submit:d=>app.activitySave({id,name:d.get('name')})});}
function assistantForm(id=''){const a=state().assistants.find(a=>a.id===id);modal(a?'Asistento kortelė':'Naujas asistentas',`<div class="form-grid">${field('Vardas, pavardė','name',a?.name||'','text','required')}${field('El. paštas','email',a?.email||'','email','required')}${check('active','Paskyra aktyvi',a?.active!==false)}</div>${a?notice('Neaktyvus asistentas negalės pradėti vizitų. Istoriniai jo įrašai išsaugomi.'):''}`,{submit:d=>app.assistantSave({id,name:d.get('name'),email:d.get('email'),active:d.has('active')})});}
function documentForm(type,cid='',previousId=''){
  const prev=state()[type].find(d=>d.id===previousId),payment=type==='payments',defaultClient=prev?.client||cid||state().clients.find(c=>manager()||C.canAccessClient(state(),actor(),c))?.id;
  const bounds=C.monthBounds(month());
  modal(payment?'Formuoti mokėjimo pranešimą':'Formuoti suteiktų paslaugų aktą',`<div class="form-grid">${sf('Paslaugos gavėjas','client',clientOptions(defaultClient,true))}${payment?field('Paslaugų mėnuo','month',prev?.month||month(),'month','required'):field('Laikotarpio pradžia','from',prev?.from||bounds[0],'date','required')}${!payment?field('Laikotarpio pabaiga','to',prev?.to||bounds[1],'date','required'):''}${!payment&&manager()?sf('Asistentas','assistant',assistantOptions(prev?.assistant||'')):''}${sf('Įtraukti valandas','source',selectOptions([{id:'approved',name:'Patikrintas koordinatoriaus'},{id:'signed',name:'Gavėjo patvirtintas parašu'},{id:'actual',name:'Visas faktines (projekto peržiūrai)'}],prev?.source||'approved',null))}${field('Dokumento data','issuedDate',day(),'date','required')}${field('Numeris (tuščias – automatinis)','number',prev?.number||'')}${field('Paslaugos teikėjo atstovas','provider',prev?.provider||'Agnė Janušienė','text','required')}</div>${payment?`<div id="doc-finance" class="finance-preview"></div>`:notice('Pradžia, pabaiga ir valandų skaičius bus automatiškai paimti iš faktinių vizitų. Kokybės vertinimas ir parašai paliekami užpildyti ranka.')}<div id="doc-preview" class="mini-note"></div>`,{wide:true,submitLabel:'Suformuoti projektą',submit:d=>{const [from,to]=payment?C.monthBounds(d.get('month')):[d.get('from'),d.get('to')],c=state().clients.find(c=>c.id===d.get('client'));const finance=prev?.finance&&prev.client===c.id&&prev.month===d.get('month')?prev.finance:currentFinance(c,d.get('month'));const id=app.createDocument(type,{client:c.id,from,to,assistant:d.get('assistant')||'',source:d.get('source'),issuedDate:d.get('issuedDate'),provider:d.get('provider'),number:d.get('number'),finance,previousId});setTimeout(()=>showDocument(type,id),0);}});
  const update=()=>{const form=$('#modal-form'),d=new FormData(form),c=state().clients.find(c=>c.id===d.get('client'));let from,to;try{[from,to]=payment?C.monthBounds(d.get('month')):[d.get('from'),d.get('to')];}catch{return;}const vs=C.visitsFor(state(),{client:c.id,assistant:actor().role==='assistant'?worker:d.get('assistant')||'',from,to,source:d.get('source')});$('#doc-preview').innerHTML=`<b>${vs.length} vizitai · ${fh(C.sumMinutes(vs))} val.</b> · ${e(from)} — ${e(to)}`;if(payment){const f=prev?.finance&&prev.client===c.id&&prev.month===d.get('month')?prev.finance:currentFinance(c,d.get('month'));$('#doc-finance').innerHTML=f?`<b>Gavėjo parametrai nuo ${e(f.from)}</b><p>${e(ruleNames[f.rule])}<br>Įkainis: ${f.rate.toFixed(2)} Eur / val. · kompensacija: ${f.comp.toFixed(2)} Eur · nustatyta suma: ${f.contribution.toFixed(2)} Eur</p><small>Naujai versijai išlaikomi ankstesnio dokumento parametrai, jei gavėjas ir mėnuo nepasikeitė.</small>`:notice('Šiam gavėjui ir mėnesiui nėra mokėjimo parametrų. Pirmiausia užpildykite juos gavėjo kortelėje.','warn');}};
  $('#modal-form').addEventListener('change',update);update();
}
function showDocument(type,id){const d=C.visibleDocs(state(),actor(),type).find(x=>x.id===id);C.assert(d,'Dokumentas nepasiekiamas.');const stale=C.staleDocument(state(),d);modal(e(d.number)+' · v'+(d.version||1),`<div class="detail-meta">${status(d.status)}${stale?badge('Pasenusi versija','red'):badge('Duomenys aktualūs','green')}</div>${stale?notice('Po formavimo pasikeitė įtraukiami vizitai ar jų patikros būsena. Suformuokite naują versiją.','warn'):''}<div class="doc-summary"><h3>${e(d.name)}</h3><p>${e(d.from)} — ${e(d.to)} · <b>${fh(d.minutes||0)} val.</b>${type==='payments'?` · Mokėti <b>${money(d.paid)} Eur</b>`:''}</p><small>Formuotojas: ${e(roleNames[d.generatedBy]||an(d.generatedBy))} · ${dt(d.created)}</small></div><div class="actions wrap">${button(stale||d.status!=='approved'?'Spausdinti projektą / PDF':'Spausdinti / PDF','doc-print',id,'primary',`data-type="${type}"`)}${button('Nauja versija','doc-version',id,'secondary',`data-type="${type}"`)}</div>${manager()&&d.status!=='approved'&&!stale?`<div class="approval-box">${check('checked','Peržiūrėjau laikotarpį, vizitus, valandas'+(type==='payments'?', mokėjimo parametrus ir sumas':'')+'. Patvirtinu dokumentą spausdinti.')}<div class="actions">${button('Patvirtinti galutinę versiją','doc-approve',id,'primary',`data-type="${type}"`)}</div></div>`:''}${type==='serviceActs'?'<div class="quality-preview"><h3>Paslaugų gavėjo vertinimas</h3><p>□ Suteiktos paslaugos mane tenkina, nusiskundimų neturiu.</p><p>□ Suteiktos paslaugos manęs netenkina.</p><p>Pastabos: _____________________________________</p><small>Pildoma ranka atspausdintame akte. Toliau – gavėjo, asistento ir paslaugos teikėjo parašų vietos.</small></div>':''}<h3>Įtrauktų vizitų momentinė kopija</h3>${table(['Data','Asistentas','Pradžia','Pabaiga','Val.'],(d.rows||[]).map(r=>`<tr><td>${e(r.date)}</td><td>${e(r.assistantName)}</td><td>${r.startISO?time(r.startISO):e(r.start||'–')}</td><td>${r.endISO?time(r.endISO):e(r.end||'–')}</td><td class="numeric">${fh(r.minutes||0)}</td></tr>`))}<p class="muted">Atspausdinto dokumento gavėjo, asistento ar teikėjo parašai įrašomi ranka. Galutinis dokumentas saugomas su jo formavimo metu naudotais duomenimis.</p>`,{wide:true});}
function printSignature(label,name){return `<div class="print-sign"><span>${label}</span><span>${e(name)}<small>(vardas ir pavardė)</small></span><span>________________<small>(parašas)</small></span><span>________________<small>(data)</small></span></div>`;}
const paymentLegal=`Nuo 2024 02 23 pasikeitus Lietuvos Respublikos Socialinės apsaugos ir darbo ministro įsakymui „Dėl Lietuvos Respublikos asmens su negalia teisių apsaugos pagrindų įstatymo 27 straipsnio įgyvendinimo“ ir mokėjimo apskaičiavimo tvarkai, keitėsi ir asmeninės pagalbos apmokėjimo tvarka bei dydis. Pagal naują tvarkos aprašą, jeigu asmeniui paskirta ir mokama individualios pagalbos teikimo išlaidų kompensacija pagal Lietuvos Respublikos tikslinių kompensacijų įstatymą, asmens mokėjimo už asmeninę pagalbą dydis neturi viršyti:`;
function documentHTML(type,d){
  const watermark=d.printDraft?`<div class="print-watermark">${d.stale?'PROJEKTAS · DUOMENYS PASIKEITĘ':'PROJEKTAS · NEPATVIRTINTA'}</div>`:'';
  const meta=`<div class="print-meta">${e(d.number)} · v${d.version||1} · suformuota ${e(d.created?.slice(0,10))}</div>`;
  if(type==='payments')return `<article class="print-document payment">${watermark}<div class="approval-stamp">PATVIRTINTA<br>VšĮ Socialinių paslaugų informacijos centras<br>Direktorė 2022 m. 06 mėn. 01 d.<br>ĮSAKYMAS Nr. ĮS220601</div><h1>MOKĖJIMO PRANEŠIMAS Nr. ${e(d.number)}</h1><p class="print-center">${new Date(d.issuedDate+'T12:00:00').toLocaleDateString('lt-LT',{year:'numeric',month:'long',day:'numeric'})}</p><p>Asmeninio asistento paslaugų teikimo sutarties ${e(d.contract)} mokėjimo pranešimas.<br>Šiuo pranešimu informuojame, kad ${e(d.month.slice(0,4))} m. ${e(d.month.slice(5))} mėn. buvo suteiktos ${fh(d.minutes)} val. asmeninio asistento paslaugų.</p><ul><li>Asmeninės pagalbos paslaugos įkainis ${money(Math.round(d.finance.rate*100))} Eur/val.</li><li>Visa suteiktų paslaugų kaina už einamą mėnesį ${fh(d.minutes)} val. × ${money(Math.round(d.finance.rate*100))} Eur = ${money(d.total)} Eur.</li><li>Valstybės biudžeto lėšomis kompensuota paslaugų kaina už einamą mėnesį ${money(d.funded)} Eur.</li><li>Individualios pagalbos teikimo išlaidų kompensacijos dydis ${money(Math.round(d.finance.comp*100))} Eur.</li><li>Tiksli suteiktų paslaugų kaina, kurią moka klientas už einamą mėnesį ${money(d.paid)} Eur.</li></ul><p class="pay-total">PRAŠOME MOKĖTI ${money(d.paid)} Eur.</p><div class="legal-copy"><p>${paymentLegal}</p><ul><li>20 procentų šios kompensacijos dydžio, jei asmeniui nustatytas pirmo ar antro lygio individualios pagalbos teikimo išlaidų kompensacijos poreikis (iki 2023 m. gruodžio 31 d. – pirmojo ar antrojo lygio specialusis nuolatinės slaugos poreikis; iki 2018 m. gruodžio 31 d. – specialusis nuolatinės slaugos poreikis);</li><li>30 procentų šios kompensacijos dydžio, jei asmeniui nustatytas trečio ar ketvirto lygio individualios pagalbos teikimo išlaidų kompensacijos poreikis (iki 2023 m. gruodžio 31 d. – pirmojo ar antrojo lygio specialusis nuolatinės priežiūros (pagalbos) poreikis; iki 2018 m. gruodžio 31 d. – specialusis nuolatinės priežiūros (pagalbos) poreikis).</li></ul><p>Jeigu nėra paskirta individualios pagalbos teikimo išlaidų kompensacija, mokėjimo už asmeninę pagalbą dydis negali viršyti 20 procentų asmeninės pagalbos teikimo išlaidų dydžio ir 20 procentų asmens pajamų. Mokėjimo už asmeninę pagalbą, kai asmeniui neskirta ir nemokama individualios pagalbos teikimo išlaidų kompensacija, dydį savivaldybės administracija/teikėjas apskaičiuoja atsižvelgiant į asmens, kuriam numatoma teikti asmeninę pagalbą pajamas ir Valstybės remiamų pajamų dydį.</p></div><div class="print-signatures"><p>Susipažinau ir sutinku:</p>${printSignature('Klientas',d.name)}${printSignature('Paslaugos teikėjas',d.provider)}</div>${meta}</article>`;
  const names=[...new Set(d.rows.map(r=>r.assistantName))];
  return `<article class="print-document service-act">${watermark}<div class="print-center">VšĮ Socialinių paslaugų informacijos centras</div><h1>FAKTIŠKAI SUTEIKTŲ ASMENINĖS PAGALBOS PASLAUGŲ AKTAS</h1><p class="print-center">Nr. ${e(d.number)} · ${e(d.issuedDate)}</p><p><b>Paslaugos gavėjas:</b> ${e(d.name)}<br><b>Sutartis:</b> ${e(d.contract)}<br><b>Paslaugų teikimo laikotarpis:</b> ${e(d.from)} — ${e(d.to)}</p><table class="act-print-table"><thead><tr><th>Data</th><th>Asmeninis asistentas</th><th>Paslaugos pradžia</th><th>Paslaugos pabaiga</th><th>Valandų skaičius</th></tr></thead><tbody>${d.rows.map(r=>`<tr><td>${e(r.date)}</td><td>${e(r.assistantName)}</td><td>${r.startISO?dt(r.startISO):e(r.start||'–')}</td><td>${r.endISO?dt(r.endISO):e(r.end||'–')}</td><td>${fh(r.minutes)}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="4"><b>Iš viso suteikta paslaugų</b></td><td><b>${fh(d.minutes)} val.</b></td></tr></tfoot></table><div class="act-confirmation"><p class="print-act-context">Aktas ${e(d.number)} · ${e(d.name)} · ${e(d.from)} — ${e(d.to)} · ${fh(d.minutes)} val.</p><div class="quality-block"><h2>Paslaugų gavėjo vertinimas</h2><p>Pažymėkite tinkamą variantą:</p><p>□ Suteiktos paslaugos mane tenkina, nusiskundimų neturiu.</p><p>□ Suteiktos paslaugos manęs netenkina.</p><p>Pastabos: ____________________________________________________________<br>____________________________________________________________________</p><p>Patvirtinu, kad šiame akte pateikta informacija yra teisinga.</p></div><div class="print-signatures">${printSignature('Paslaugos gavėjas',d.name)}${names.map(name=>printSignature('Asmeninis asistentas',name)).join('')}${printSignature('Paslaugos teikėjas',d.provider)}</div>${meta}</div></article>`;
}
function printDocument(type,id){const doc=app.documentForPrint(type,id);$('#print-zone').innerHTML=documentHTML(type,doc);$('#modal').close();document.body.classList.add('printing');window.print();setTimeout(()=>document.body.classList.remove('printing'),100);}
function download(name,text,mime='text/plain;charset=utf-8'){const blob=new Blob([text],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function backup(){download('spic-duomenu-kopija-'+day()+'.json',JSON.stringify(state(),null,2),'application/json');}
function restore(){modal('Atkurti duomenų kopiją',notice('Prieš atkūrimą atsisiųskite esamą kopiją. Atkūrimas pakeis šioje naršyklėje saugomus demonstracijos duomenis.','warn')+'<label class="field">JSON duomenų kopija<input id="restore-file" type="file" accept=".json,application/json" required></label>'+check('replace','Suprantu, kad esami duomenys bus pakeisti.'),{submitLabel:'Atkurti kopiją',submit:d=>{C.assert(d.has('replace'),'Patvirtinkite duomenų pakeitimą.');C.assert(restore.ready,'Pasirinkite ir palaukite, kol bus patikrintas failas.');const next=C.migrate(restore.ready);next.revision=state().revision+1;next.audit.unshift({id:C.uid('audit'),at:new Date().toISOString(),user:actor().role,action:'Duomenų atkūrimas iš kopijos',target:'visi duomenys'});localStorage.setItem(C.STORAGE_KEY,JSON.stringify(next));app.s=next;loadError='';app.storage=localStorage;}});restore.ready=null;$('#restore-file').onchange=async ev=>{try{const f=ev.target.files[0];C.assert(f&&f.size<10e6,'Pasirinkite JSON failą iki 10 MB.');const next=C.migrate(JSON.parse(await f.text()));for(const c of next.clients)C.validateClient(next,c);restore.ready=next;toast('Kopija patikrinta: '+next.clients.length+' gavėjai.');}catch(error){restore.ready=null;toast(error.message,true);}};}
function htmlDownload(){const doc=document.documentElement.cloneNode(true);doc.querySelectorAll('[data-seed]').forEach(x=>x.remove());const script=document.createElement('script');script.dataset.seed='1';script.textContent='window.SPIC_INITIAL='+JSON.stringify(state()).replaceAll('<','\\u003c')+';';doc.querySelector('head').append(script);doc.querySelector('#modal').removeAttribute('open');doc.querySelector('#modal').innerHTML='';doc.querySelector('#print-zone').innerHTML='';download('spic-prototipas-v13.html','<!doctype html>\n'+doc.outerHTML,'text/html;charset=utf-8');}
function guide(){modal('Demonstracijos maršrutas',`<ol class="guide"><li><b>Asistentas</b><p>„Mano diena“ → planuoti dieną ir atvykimo laiką → pradėti vizitą → užbaigti, pažymėti veiklas → gavėjo parašas.</p></li><li><b>Įrašo taisymas</b><p>Atidaryti savo vizitą → prašyti leidimo → koordinatorius patvirtina → asistentas taiso → naujas parašas ir patikra.</p></li><li><b>Mėnesio uždarymas</b><p>Ataskaitos → paslaugų aktas pasirinktam laikotarpiui → mokėjimo pranešimas → koordinatoriaus peržiūra → spausdinimas ir rankiniai parašai.</p></li><li><b>Administratorius</b><p>Leistinų veiklų katalogas → gavėjo veiklos → asistentų registras → CSV importo patikra → JSON kopija.</p></li><li><b>Darbas be interneto</b><p>Nustatymuose įjungti pasirenkamą modulį → atjungti ryšį viršuje → registruoti vizitą → atkurti ryšį ir stebėti demonstracinės eilės išvalymą.</p></li></ol>${notice('Tai susitikimui skirta demonstracija su vietiniais duomenimis. Produkcinės tapatybės, atsarginių kopijų, pašto ir sinchronizavimo paslaugos čia neprijungtos.')}`,{wide:true});}
function exportVisits(){const f=q.visits||{},v=state().visits.filter(v=>(manager()||v.assistant===worker)&&(!f.search||(cn(v.client)+' '+an(v.assistant)).toLowerCase().includes(f.search.toLowerCase()))&&(!f.from||v.date>=f.from)&&(!f.to||v.date<=f.to)&&(!f.status||v.review===f.status)&&(!f.assistant||v.assistant===f.assistant)&&(!f.issues||C.visitIssues(state(),v).length));download('spic-vizitai.csv',C.toCSV([['Gavėjas','Asistentas','Data','Pradžia','Pabaiga','Minutės','Valandos','Veiklos','Būsena','Versija'],...v.map(x=>[cn(x.client),an(x.assistant),x.date,dt(x.startISO),dt(x.endISO),C.integerMinutes(x),(C.integerMinutes(x)/60).toFixed(2),x.activities.map(a=>a.name).join(', '),statusLabels[x.review],x.rev])]),'text/csv;charset=utf-8');}
function reportExport(print=false){const {from,to,cs,v,mode}=reportData();const rows=cs.map(c=>{const r=v.filter(v=>v.client===c.id),p=mode==='year'?Array.from({length:12},(_,i)=>C.monthlyPlan(c,from.slice(0,4)+'-'+String(i+1).padStart(2,'0')).hours).reduce((a,b)=>a+b,0):C.monthlyPlan(c,from.slice(0,7)).hours;return [c.name,p,(C.sumMinutes(r)/60).toFixed(2),(C.sumMinutes(r.filter(x=>x.review==='approved'))/60).toFixed(2),(C.sumMinutes(r.filter(C.isSigned))/60).toFixed(2)];});const heads=['Gavėjas','Paskirta val.','Faktiškai val.','Patikrinta val.','Gavėjo patvirtinta val.'];if(print){$('#print-zone').innerHTML=`<article class="print-document"><h1>Asmeninės pagalbos paslaugų suvestinė</h1><p>${e(from)} — ${e(to)}</p>${table(heads,rows.map(r=>'<tr>'+r.map(x=>`<td>${e(x)}</td>`).join('')+'</tr>'))}<p>Suteikta iš viso: ${fh(C.sumMinutes(v))} val.</p></article>`;window.print();}else download('spic-ataskaita-'+from+'-'+to+'.csv',C.toCSV([heads,...rows]),'text/csv;charset=utf-8');}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const {action:a,id,type}=b.dataset;safe(()=>{
  switch(a){
    case 'nav':tab=id;render();$('#main').focus();break;
    case 'home':ev.preventDefault();tab=actor().role==='assistant'?'mine':'overview';render();break;
    case 'menu':$('#sidebar').classList.toggle('open');break;
    case 'close':$('#modal').close();break;
    case 'guide':guide();break;
    case 'worker-demo':app.actor={role:'assistant',assistantId:worker};tab='mine';render();break;
    case 'network':if(state().online){app.setOnline(false);render();toast('Ryšys atjungtas demonstracijai.');}else{app.setOnline(true);render();toast('Ryšys atkurtas. Vietinė eilė apdorota (demonstracija).');}break;
    case 'clear-filter':q[id]={};render();break;
    case 'new-plan':scheduleForm();break;
    case 'plan-client':scheduleForm('',id);break;
    case 'edit-plan':scheduleForm(id);break;
    case 'cancel-plan':reasonModal('Atšaukti suplanuotą vizitą',r=>app.scheduleCancel(id,r));break;
    case 'week-prev':{const d=new Date(week+'T12:00:00');d.setDate(d.getDate()-7);week=C.localDay(d);render();break;}
    case 'week-next':{const d=new Date(week+'T12:00:00');d.setDate(d.getDate()+7);week=C.localDay(d);render();break;}
    case 'week-today':week=day();render();break;
    case 'start':{const idv=app.startVisit(id);render();showVisit(idv);break;}
    case 'start-plan':{const p=state().schedule.find(p=>p.id===id),idv=app.startVisit(p.client,id);render();showVisit(idv);break;}
    case 'visit':showVisit(id);break;
    case 'finish':finishForm(id);break;
    case 'sign':signForm(id);break;
    case 'edit-visit':editVisit(id);break;
    case 'request':reasonModal('Prašyti leidimo taisyti',r=>app.requestCorrection(id,r),'Ką norite pakeisti ir kodėl?');break;
    case 'request-approve':reasonModal('Suteikti leidimą taisyti',r=>app.decideCorrection(id,true,r),'Koordinatoriaus komentaras');break;
    case 'request-reject':reasonModal('Atmesti taisymo prašymą',r=>app.decideCorrection(id,false,r),'Atmetimo priežastis');break;
    case 'approve-visit':app.reviewVisit(id,true);$('#modal').close();render();toast('Įrašas patikrintas.');break;
    case 'return-visit':reasonModal('Grąžinti įrašą taisyti',r=>app.reviewVisit(id,false,r));break;
    case 'requests-pending':requestArchive=false;render();break;
    case 'requests-archive':requestArchive=true;render();break;
    case 'new-client':clientForm();break;
    case 'client':clientForm(id);break;
    case 'finance':financeForm(id);break;
    case 'new-activity':activityForm();break;
    case 'activity':activityForm(id);break;
    case 'activity-toggle':{const activity=state().activities.find(x=>x.id===id),n=state().clients.filter(c=>c.allowed.includes(id)).length;modal(activity.active?'Išjungti veiklą?':'Aktyvuoti veiklą?',`<p><b>${e(activity.name)}</b> priskirta ${n} gavėjams.</p>${notice('Istoriniai vizitai ir jų veiklų pavadinimai išsaugomi. Užbaigiant šiuo metu vykstantį vizitą reikės pasirinkti aktyvią leistiną veiklą.','warn')}`,{submitLabel:activity.active?'Išjungti':'Aktyvuoti',submit:()=>app.activityToggle(id)});break;}
    case 'new-assistant':assistantForm();break;
    case 'assistant':assistantForm(id);break;
    case 'new-payment':documentForm('payments');break;
    case 'new-act':documentForm('serviceActs');break;
    case 'act-client':documentForm('serviceActs',id);break;
    case 'doc-view':showDocument(type,id);break;
    case 'doc-version':documentForm(type,'',id);break;
    case 'doc-print':printDocument(type,id);break;
    case 'doc-approve':app.approveDocument(type,id,$('#modal-form [name="checked"]')?.checked);showDocument(type,id);render();toast('Dokumentas patvirtintas.');break;
    case 'visits-csv':exportVisits();break;
    case 'reports-csv':reportExport();break;
    case 'reports-print':reportExport(true);break;
    case 'audit-csv':download('spic-veiksmu-istorija.csv',C.toCSV([['Laikas','Naudotojas','Veiksmas','Objektas'],...state().audit.map(a=>[a.at,a.user,a.action,a.target])]),'text/csv;charset=utf-8');break;
    case 'remind':app.commit('El. pašto priminimo demonstracija',id,s=>s.reminded.push({key:id,at:app.stamp}));toast('Priminimas užregistruotas. Laiškas demonstracijoje nesiunčiamas.');render();break;
    case 'template-clients':{const c=state().clients[0];download('spic-gaveju-importo-sablonas.csv',C.toCSV([C.CLIENT_HEADERS,C.CLIENT_HEADERS.map(k=>k==='hours'?C.monthlyPlan(c,month()).hours:k==='planFrom'?month():k==='allowed'?c.allowed.map(id=>state().activities.find(a=>a.id===id)?.name).join('|'):c[k]||'')]),'text/csv;charset=utf-8');break;}
    case 'template-assistants':download('spic-asistentu-importo-sablonas.csv',C.toCSV([C.ASSISTANT_HEADERS,C.ASSISTANT_HEADERS.map(k=>state().assistants[0][k])]),'text/csv;charset=utf-8');break;
    case 'apply-import':C.assert(importPreview&&!importPreview.errors.length,'Pirmiausia patikrinkite failą.');app.importRows(importPreview.kind,importPreview.parsed);importPreview=null;render();toast('Visi įrašai importuoti.');break;
    case 'cancel-import':importPreview=null;render();break;
    case 'backup':backup();break;
    case 'restore':restore();break;
    case 'html-download':htmlDownload();break;
    case 'reset':modal('Atkurti demonstracijos pradžią?',notice('Visi šiame įrenginyje atlikti demonstracijos pakeitimai bus pakeisti pradiniais pavyzdžiais. Prieš tęsdami atsisiųskite JSON kopiją.','warn')+check('reset','Patvirtinu pradinių demonstracijos duomenų atkūrimą.'),{submitLabel:'Atkurti',submit:d=>{C.assert(d.has('reset'),'Pažymėkite patvirtinimą.');const next=C.seedState();next.revision=state().revision+1;localStorage.setItem(C.STORAGE_KEY,JSON.stringify(next));app.s=next;loadError='';app.storage=localStorage;}});break;
  }
});});
document.addEventListener('change',ev=>{if(ev.target.id==='role-select'){app.actor={role:ev.target.value,assistantId:worker};tab=actor().role==='assistant'?'mine':'overview';render();}if(ev.target.id==='worker-select'){worker=ev.target.value;app.actor.assistantId=worker;render();}});
document.addEventListener('submit',ev=>{
  if(ev.target.dataset.filter){ev.preventDefault();safe(()=>{const form=ev.target,d=Object.fromEntries(new FormData(form));if(d.from&&d.to)C.assert(d.from<=d.to,'Pradžia turi būti ankstesnė už pabaigą.');if(ev.target.dataset.filter==='reports'){C.assert(/^\d{4}(-(0[1-9]|1[0-2]))?$/.test(d.period),'Nurodykite metus arba mėnesį, pvz., 2026-10.');if(d.mode==='month')C.assert(d.period.length===7,'Mėnesio ataskaitai nurodykite metus ir mėnesį.');}q[form.dataset.filter]=d;render();});}
  if(ev.target.id==='settings-form'){ev.preventDefault();safe(()=>{const d=new FormData(ev.target);app.admin();app.commit('Nustatymų pakeitimas','nustatymai',s=>{s.settings={days:Number(d.get('days')),threshold:Number(d.get('threshold')),offline:d.has('offline'),gps:d.has('gps')};});render();toast('Nustatymai išsaugoti.');});}
  if(ev.target.id==='import-form'){ev.preventDefault();safe(async()=>{const d=new FormData(ev.target),file=d.get('file');C.assert(file&&file.size<2e6,'Pasirinkite CSV failą iki 2 MB.');const parsed=C.parseCSV(await file.text()),kind=d.get('kind'),result=C.prepareImport(state(),kind,parsed);importPreview={...result,parsed,kind};render();});}
});
window.addEventListener('storage',ev=>{if(ev.key===C.STORAGE_KEY)toast('Duomenys pakeisti kitame lange. Atnaujinkite puslapį prieš atlikdami pakeitimus.',true);});
window.addEventListener('afterprint',()=>document.body.classList.remove('printing'));
document.addEventListener('visibilitychange',()=>{if(!document.hidden)render();});
// Naršyklės tikras ryšys ir demonstracijos perjungiklis naudoja tą pačią eilę.
window.addEventListener('offline',()=>{safe(()=>{app.setOnline(false);render();});});
window.addEventListener('online',()=>safe(()=>{app.setOnline(true);render();toast('Ryšys atkurtas. Demonstracinė eilė apdorota.');}));
if(location.protocol==='https:'||location.hostname==='localhost')navigator.serviceWorker?.register('./sw.js').catch(()=>{});
window.SPICDemo={get state(){return state();},get actor(){return actor();},render,store:app};
render();
